con:config.script:
import java.time.LocalDate
import java.time.format.DateTimeFormatter

def hoje = LocalDate.now()

// --- Período do mês atual ---
def dataInicial = hoje.withDayOfMonth(1)
def dataFinal   = hoje.withDayOfMonth(hoje.lengthOfMonth())
def formatoData = DateTimeFormatter.ofPattern('yyyy-MM-dd')

// --- Mês e ano atuais (sem zero à esquerda) ---
def mes = hoje.monthValue   // 1 a 12
def ano = hoje.year         // ex: 2026

// Salva no TestCase
testRunner.testCase.setPropertyValue('dataInicial', dataInicial.format(formatoData))
testRunner.testCase.setPropertyValue('dataFinal',   dataFinal.format(formatoData))
testRunner.testCase.setPropertyValue('mes',         mes.toString())
testRunner.testCase.setPropertyValue('ano',         ano.toString())

log.info "dataInicial = ${dataInicial.format(formatoData)}"
log.info "dataFinal   = ${dataFinal.format(formatoData)}"
log.info "mes         = ${mes}"
log.info "ano         = ${ano}"
